# Calculate the neighbor change for each borough
def get_neighbor_change(row, df):
    if row['borough'] in neighbors:
        neighbor_changes = [df.loc[df['borough'] == neighbor, 'change'].values[0] for neighbor in neighbors[row['borough']]]
        return np.mean(neighbor_changes)
    else:
        return 0

df['neighbor_change'] = df.apply(get_neighbor_change, axis=1, args=(df,))
